function card(u,readonly){var c=calc(u),cls=c.capPct>=100?"red":c.capPct>=80?"amber":"green";if(readonly){return '<div class="card"><div class="cardHead"><div><h3>'+esc(u.name)+'</h3><div class="meta">'+esc(u.id)+'<br>'+esc(u.upi||"UPI not added")+' • APK: '+esc(u.apk||u.mobile||"Not added")+'</div></div><div>'+statusBadge(u)+'<span class="badge '+cls+'">Available '+money(c.collectionCapacity)+'</span></div></div><div class="metrics">'+metric("Available Collection",money(c.collectionCapacity))+metric("UPI ID",esc(u.upi||"-"))+metric("APK / Mobile",esc(u.apk||u.mobile||"-"))+'</div><div class="bar"><i style="width:'+c.capPct+'%"></i></div><div class="cardActions"><button class="btn ghost sm" onclick="SF.readDetail(\''+u.id+'\')">View GPay Details</button></div></div>'}return '<div class="card"><div class="cardHead"><div><h3>'+esc(u.name)+'</h3><div class="meta">'+esc(u.id)+' • '+esc(u.telegram||"-")+'<br>'+esc(u.upi||"UPI not added")+'</div><div class="modeStrip">'+modePill(u)+'</div></div><div>'+statusBadge(u)+'<span class="badge '+cls+'">'+c.capPct.toFixed(0)+'% used</span></div></div><div class="metrics">'+metric("Collection",money(c.collection))+metric("Available Collection",money(c.collectionCapacity))+(u.fundingMode==="deposit"?metric("Confirmed Deposit",usdt(c.confirmedDepositUsdt))+metric("Withdrawn",money(c.inrReceived)):metric("Withdrawn",money(c.inrReceived))+metric("Commission",money(c.commissionEarned)))+metric("Pending From User",money(c.pending))+metric("Frozen",money(c.frozen))+'</div><div class="bar"><i style="width:'+c.capPct+'%"></i></div><div class="cardActions"><button class="btn primary sm" onclick="SF.openUser(\''+u.id+'\')">Open Card</button><button class="btn ghost sm" onclick="SF.copyUser(\''+u.id+'\')">Copy User Link</button>'+ (staffRole==="admin"?'<button class="btn red sm" onclick="SF.deleteUser(\''+u.id+'\')">Delete</button>':'') +'</div></div>'}
