window.addEventListener("hashchange",render);window.addEventListener("storage",render);render();if(backend.configured){backend.subscribe(function(){refreshFromBackend()});refreshFromBackend();backend.authenticated().then(function(ok){if(ok){staffRole=ok;sessionStorage.setItem(AUTH_KEY,"1");render()}})}
